CREATE TABLE projects (id uuid PRIMARY KEY, name text NOT NULL, version integer NOT NULL DEFAULT 0, event_sequence bigint NOT NULL DEFAULT 0, configuration jsonb NOT NULL DEFAULT '{}');
CREATE TABLE scenario_runs (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, status text NOT NULL CHECK(status IN ('active','resetting','retired')), scenario_version text NOT NULL, scenario_date date NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,project_id));
CREATE UNIQUE INDEX one_active_run ON scenario_runs(project_id) WHERE status='active';
CREATE TABLE members (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, username text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, roles text[] NOT NULL, telegram_sender_id text, remote_user_id text, UNIQUE(project_id,telegram_sender_id));
CREATE TABLE channel_bindings (chat_id text PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects);
CREATE TABLE sessions (token_hash text PRIMARY KEY, member_id uuid NOT NULL REFERENCES members, csrf_token text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts integer NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE locations (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, name text NOT NULL, aliases text[] NOT NULL);
CREATE TABLE materials (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, code text NOT NULL, name text NOT NULL, unit text NOT NULL, coverage numeric, aliases text[] NOT NULL, UNIQUE(project_id,code));
CREATE TABLE work_items (id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, location_id uuid REFERENCES locations, name text NOT NULL, weight numeric NOT NULL CHECK(weight>=0), status text NOT NULL, version integer NOT NULL DEFAULT 0, area numeric, allowance numeric, material_id uuid REFERENCES materials, required_date date, FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE dependencies (id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, work_item_id uuid NOT NULL REFERENCES work_items, description text NOT NULL, resolved boolean NOT NULL DEFAULT false, FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE inventory_movements (id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, material_id uuid NOT NULL REFERENCES materials, quantity numeric NOT NULL, unit text NOT NULL, operation_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,run_id,operation_key), FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE private_files (id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, content_type text NOT NULL, sha256 text NOT NULL, size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 0 AND 20971520), restricted boolean NOT NULL DEFAULT false, FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE domain_events (event_id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, sequence bigint NOT NULL, project_version integer NOT NULL, operation_id uuid NOT NULL, type text NOT NULL, occurred_at timestamptz NOT NULL, evidence_ids uuid[] NOT NULL, payload jsonb NOT NULL, schema_version integer NOT NULL, UNIQUE(project_id,sequence), FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE scheduled_jobs (job_id uuid PRIMARY KEY, kind text NOT NULL, project_id uuid NOT NULL, run_id uuid NOT NULL, operation_id uuid NOT NULL, dedupe_key text NOT NULL UNIQUE, payload_version integer NOT NULL, payload jsonb NOT NULL, status text NOT NULL CHECK(status IN ('pending','leased','succeeded','failed','uncertain','cancelled')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL, due_at timestamptz, lease_owner text, lease_expires_at timestamptz, last_error text, condition text, result_reference text, FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE INDEX job_claim ON scheduled_jobs(status,available_at);
CREATE TABLE outbox_entries (id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, job_id uuid NOT NULL UNIQUE REFERENCES scheduled_jobs, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE worker_heartbeats (id text PRIMARY KEY, seen_at timestamptz NOT NULL);
